// Init Run State
// Reads the form, sets up configuration and the loop's state object.
// Edit CONFIG below to tune the workflow without touching other nodes.

const CONFIG = {
  // --- Gemini (AI ranking) ---
  // Tried in order. If a model is overloaded, timing out or out of quota, the next one is used.
  aiModels: ['gemini-3.5-flash-lite', 'gemini-3.5-flash', 'gemini-3.1-flash-lite'],
  aiThinkingLevel: 'minimal',       // minimal = fastest; scoring a job post needs no deep reasoning
  aiMinIntervalMs: 4500,            // minimum gap between Gemini calls (free-tier friendly)
  aiMaxAttemptsPerLead: 4,          // retries per posting (with backoff + model fallback)
  aiDisableAfterFailures: 3,        // after N postings in a row fail, switch the run to keyword scoring
  aiPrefilterMinScore: 2,           // only send postings with keyword score >= this to Gemini (saves quota)

  // --- Firecrawl ---
  firecrawlDelayMs: 700,            // pause between Firecrawl searches
  maxConsecutiveApiErrors: 3,       // stop the run if Firecrawl keeps failing

  // --- Closed / stale job filtering ---
  queryExclusions: ['"no longer accepting"', '"job has expired"'],
  closedPhrases: [
    'no longer accepting applications', 'no longer accepting', 'job is no longer available',
    'this job has expired', 'job has expired', 'job expired', 'position has been filled',
    'position is filled', 'applications are closed', 'applications closed', 'this job is closed',
    'job is closed', 'vacancy closed', 'not accepting applications', 'posting has closed',
    'this position is no longer', 'the job you are looking for', 'job not found',
  ],
  maxAgeDays: { 'qdr:d': 2, 'qdr:w': 10, 'qdr:m': 35, '': 0 },  // 0 = no age limit
  verifySkipDomains: ['linkedin.com'],   // page check is never run on these (snippet signals only)

  // --- Location matching (for the "Only keep jobs in my locations" filter) ---
  // Typing a country also accepts its cities listed here; typing a city rejects jobs that are
  // clearly in another known place. Places not listed still work: they match by name, and jobs
  // whose location can't be recognised are kept. Add your own countries/cities freely.
  locationGroups: {
    'united states': { aliases: ['united states', 'usa', 'u.s.'], cities: ['new york', 'san francisco', 'seattle', 'austin', 'boston', 'chicago', 'los angeles', 'denver', 'atlanta', 'miami', 'dallas', 'washington dc'] },
    'united kingdom': { aliases: ['united kingdom', 'uk', 'england', 'scotland', 'great britain'], cities: ['london', 'manchester', 'edinburgh', 'birmingham', 'bristol', 'cambridge', 'oxford'] },
    canada: { aliases: ['canada'], cities: ['toronto', 'vancouver', 'montreal', 'ottawa', 'calgary'] },
    germany: { aliases: ['germany', 'deutschland'], cities: ['berlin', 'munich', 'hamburg', 'frankfurt', 'cologne'] },
    netherlands: { aliases: ['netherlands', 'holland'], cities: ['amsterdam', 'rotterdam', 'the hague', 'utrecht', 'eindhoven'] },
    ireland: { aliases: ['ireland'], cities: ['dublin', 'cork'] },
    france: { aliases: ['france'], cities: ['paris', 'lyon'] },
    spain: { aliases: ['spain'], cities: ['madrid', 'barcelona'] },
    sweden: { aliases: ['sweden'], cities: ['stockholm'] },
    poland: { aliases: ['poland'], cities: ['warsaw', 'krakow'] },
    uae: { aliases: ['uae', 'united arab emirates', 'emirates'], cities: ['dubai', 'abu dhabi', 'sharjah'] },
    'saudi arabia': { aliases: ['saudi arabia', 'saudi', 'ksa'], cities: ['riyadh', 'jeddah', 'dammam'] },
    qatar: { aliases: ['qatar'], cities: ['doha'] },
    singapore: { aliases: ['singapore'], cities: [] },
    australia: { aliases: ['australia'], cities: ['sydney', 'melbourne', 'brisbane', 'perth'] },
    india: { aliases: ['india'], cities: ['bangalore', 'bengaluru', 'mumbai', 'delhi', 'new delhi', 'pune', 'chennai', 'noida', 'gurgaon', 'gurugram'] },
    pakistan: { aliases: ['pakistan'], cities: ['lahore', 'karachi', 'islamabad', 'rawalpindi', 'faisalabad', 'peshawar', 'multan'] },
    egypt: { aliases: ['egypt'], cities: ['cairo'] },
    nigeria: { aliases: ['nigeria'], cities: ['lagos', 'abuja'] },
    kenya: { aliases: ['kenya'], cities: ['nairobi'] },
    'south africa': { aliases: ['south africa'], cities: ['cape town', 'johannesburg'] },
    brazil: { aliases: ['brazil', 'brasil'], cities: ['sao paulo', 'são paulo', 'rio de janeiro'] },
    mexico: { aliases: ['mexico'], cities: ['mexico city', 'guadalajara'] },
    japan: { aliases: ['japan'], cities: ['tokyo', 'osaka'] },
    malaysia: { aliases: ['malaysia'], cities: ['kuala lumpur'] },
    philippines: { aliases: ['philippines'], cities: ['manila'] },
    turkey: { aliases: ['turkey', 'türkiye', 'turkiye'], cities: ['istanbul', 'ankara'] },
  },
  remoteAliases: ['remote', 'work from home', 'wfh', 'fully remote', 'remote-first'],
  // "Anywhere" on the form = no location at all in searches, and nothing is filtered out
  anywhereAliases: ['anywhere', 'worldwide', 'any location', 'global'],
  otherKnownLocations: ['europe', 'emea', 'apac', 'latam', 'middle east'],

  // --- Decision-maker lookup ---
  contactRoles: [
    'CTO', '"Head of Engineering"', '"Engineering Manager"', 'Founder', 'CEO',
    '"Talent Acquisition"', '"HR Manager"',
  ],

  // Job boards: site filter for the query + regex a single posting URL must match.
  boards: {
    'LinkedIn Jobs': { site: 'linkedin.com/jobs/view', match: 'linkedin\\.com\\/jobs\\/view\\/' },
    // "reject" = listing / search-result pages on that board (not a single job)
    'Rozee.pk':      { site: 'rozee.pk', match: 'rozee\\.pk\\/', reject: '\\/job\\/jsearch|\\/jobs-in-|\\/search|\\/compan(y|ies)\\/[^/]*$|[?&]q=' },
    'Indeed':        { site: 'indeed.com', match: 'indeed\\.com\\/(viewjob|rc\\/clk|m\\/viewjob|m\\/basecamp\\/viewjob)|indeed\\.com\\/.*[?&]jk=' },
    'Bayt':          { site: 'bayt.com', match: 'bayt\\.com\\/[a-z]{2}\\/.*job' },
    'Greenhouse':    { site: 'greenhouse.io', match: 'greenhouse\\.io\\/[^/]+\\/jobs\\/\\d+' },
    'Lever':         { site: 'jobs.lever.co', match: 'jobs\\.lever\\.co\\/[^/]+\\/[0-9a-f-]{8,}' },
    'Any website':   { site: '', match: '^https?:\\/\\/' },
  },
};

const form = $('Lead Intake Form').first().json;

function asList(value) {
  if (Array.isArray(value)) return value.map(String);
  const s = String(value ?? '').trim();
  if (!s) return [];
  try {
    const parsed = JSON.parse(s);
    if (Array.isArray(parsed)) return parsed.map(String);
  } catch (e) {}
  return s.split(',').map((x) => x.trim()).filter(Boolean);
}
const yes = (v, dflt) => String(v ?? dflt).toLowerCase().startsWith('y');

// Roles and locations: multi-select dropdown + free-text "Other ..." box (comma-separated).
// Older forms with single text fields still work.
// Roles split on , ; | (not "/", so "UI/UX Designer" survives); locations also split on "/".
const splitList = (v, slash = false) => asList(v).flatMap((x) => String(x).split(slash ? /\s*[,;\/|]\s*/ : /\s*[,;|]\s*|\s+OR\s+/i))
  .map((x) => x.replace(/\s*\(anywhere\)\s*$/i, '').replace(/\s+/g, ' ').trim()).filter(Boolean);
const uniqCI = (arr) => arr.filter((x, i) => arr.findIndex((y) => y.toLowerCase() === x.toLowerCase()) === i);
const roles = uniqCI([
  ...asList(form['Roles']),
  ...splitList(form['Other roles (comma-separated)']),
  ...splitList(form['Role or skill keywords']),
].map((x) => String(x).trim()).filter(Boolean));
const locations = uniqCI([
  ...splitList(form['Locations (cities or countries, comma-separated)'], true),   // typed, any place worldwide
  ...asList(form['Quick-pick locations']),
  ...asList(form['Locations']),                                     // older form versions
  ...splitList(form['Other locations (comma-separated)'], true),
  ...splitList(form['Location'], true),
].map((x) => String(x).replace(/\s*\((anywhere|no location filter)\)\s*$/i, '').trim()).filter(Boolean));
if (!roles.length) throw new Error('Pick at least one role (or type one in "Other roles").');
if (!locations.length) throw new Error('Type at least one location (a city, a country, "Remote" or "Anywhere").');
const strictLocation = !String(form['Location filter'] || 'Only').toLowerCase().startsWith('keep all');

const targetLeads = Number(form['Maximum leads']);
if (![10, 25, 50].includes(targetLeads)) {
  throw new Error(`Invalid Maximum leads value: ${form['Maximum leads']}`);
}

const mode = String(form.Mode || '').toLowerCase().includes('job') ? 'jobs' : 'clients';
const modeLabel = mode === 'jobs' ? 'Jobs' : 'Clients';

let boardNames = asList(form['Job boards']).filter((b) => CONFIG.boards[b]);
if (!boardNames.length) boardNames = ['LinkedIn Jobs', 'Rozee.pk', 'Indeed'];
const boards = boardNames.map((name) => ({ name, ...CONFIG.boards[name] }));

const tbsMap = { 'Past 24 hours': 'qdr:d', 'Past week': 'qdr:w', 'Past month': 'qdr:m', 'Any time': '' };
const tbs = tbsMap[form['Posted within']] ?? 'qdr:w';

const rankingField = String(form['Ranking method'] || '').toLowerCase();
const rankingMode = rankingField.includes('no ranking') ? 'none'
  : rankingField.includes('keyword') ? 'keyword' : 'ai';
const rankingLabel = { ai: 'AI (Gemini)', keyword: 'Keyword', none: 'None' }[rankingMode];

const minScore = Math.min(5, Math.max(1, Number(form['Minimum fit score (1-5)'] || 3)));
const findContacts = mode === 'clients' && yes(form['Find a decision-maker? (clients mode)'], 'Yes');
const verifyOpen = yes(form['Check job is still open? (extra credits)'], 'Yes');

const existingRows = $('Load Existing Leads').all()
  .filter((i) => i.json && String(i.json['Job URL'] || '').trim());

return [{
  json: {
    form,
    mode,
    modeLabel,
    config: {
      aiModels: CONFIG.aiModels,
      aiThinkingLevel: CONFIG.aiThinkingLevel,
      aiMinIntervalMs: CONFIG.aiMinIntervalMs,
      aiMaxAttemptsPerLead: CONFIG.aiMaxAttemptsPerLead,
      aiDisableAfterFailures: CONFIG.aiDisableAfterFailures,
      aiPrefilterMinScore: CONFIG.aiPrefilterMinScore,
      firecrawlDelayMs: CONFIG.firecrawlDelayMs,
      maxConsecutiveApiErrors: CONFIG.maxConsecutiveApiErrors,
      queryExclusions: CONFIG.queryExclusions,
      closedPhrases: CONFIG.closedPhrases,
      maxAgeDays: CONFIG.maxAgeDays[tbs] ?? 0,
      verifySkipDomains: CONFIG.verifySkipDomains,
      contactRoles: CONFIG.contactRoles,
      roles,
      locations,
      rolesText: roles.join(', '),
      locationsText: locations.join(', '),
      strictLocation,
      locationGroups: CONFIG.locationGroups,
      remoteAliases: CONFIG.remoteAliases,
      anywhereAliases: CONFIG.anywhereAliases,
      otherKnownLocations: CONFIG.otherKnownLocations,
      boards,
      tbs,
      minScore: rankingMode === 'none' ? 1 : minScore,
      findContacts,
      verifyOpen,
      rankingMode,
      rankingLabel,
      useAi: rankingMode === 'ai',
    },
    targetLeads,
    newLeadsSaved: 0,
    lowFitCount: 0,
    duplicateCount: 0,
    notJobCount: 0,
    closedCount: 0,
    wrongLocationCount: 0,
    aiErrorCount: 0,
    aiFallbackCount: 0,
    consecutiveAiFailures: 0,
    aiDisabled: false,
    aiModelIdxRun: 0,
    aiNoThinkingRun: false,
    consecutiveUnsuccessfulAttempts: 0,
    consecutiveApiErrors: 0,
    lastApiError: '',
    lastAiError: '',
    lastAiCallAt: 0,
    maxRetries: Math.max(40, targetLeads * 3),
    maxAttempts: targetLeads * 25,
    attemptIndex: 0,
    savedByBoard: {},
    missesByBoard: {},
    boardSearchIdx: {},
    pageCheckedCount: 0,
    seenUrls: [],
    seenKeys: [],
    candidateQueue: [],
    existingLeadCount: existingRows.length,
    searchRunId: String($execution.id),
    startedAt: $now.toISO(),
    shouldContinue: true,
    lastOutcome: null,
    status: 'running',
    useQueue: false,
  },
}];

// Build Search Query
// Decides the next step of the loop, keeping leads balanced across the selected job boards:
//   1. The board with the fewest saved leads is always served next.
//   2. Each board gets a fair share of the target (target / boards). A board that reaches
//      its share is paused, so the others get a turn.
//   3. A board whose last DRY_AFTER results all failed (nothing found, duplicate, closed,
//      low fit, wrong location...) is marked "dry" and the remaining boards fill its share.
//      If every board is dry, all are tried again.
//   4. That board's queued results are used first (cheaper than a new search); if it has
//      none queued, it is searched.
// Each board cycles through every role x location combination on its own.

const state = $input.first().json;
const cfg = state.config;
const attempt = Number(state.attemptIndex || 0);
const consec = Number(state.consecutiveUnsuccessfulAttempts || 0);
const candidateQueue = Array.isArray(state.candidateQueue) ? state.candidateQueue : [];

const boards = cfg.boards;
const B = boards.length;
const DRY_AFTER = 6;                                    // failed results in a row before a board is "dry"
const share = Math.ceil(Number(state.targetLeads) / B);
const saved = state.savedByBoard || {};
const empty = state.missesByBoard || {};
const searches = state.boardSearchIdx || {};

const wet = boards.filter((b) => (empty[b.name] || 0) < DRY_AFTER);
let pool = wet.filter((b) => (saved[b.name] || 0) < share);
if (!pool.length) pool = wet;                           // others are dry: let the rest fill the target
let resetEmpty = false;
if (!pool.length) { pool = boards; resetEmpty = true; } // every board dry: give them all another go
const eligible = new Set(pool.map((b) => b.name));

// 1) Serve the neediest board (fewest saved leads). Use its queued results if it has any
//    (cheaper than a new search); otherwise search it.
const minSaved = Math.min(...pool.map((b) => saved[b.name] || 0));
const neediest = pool.filter((b) => (saved[b.name] || 0) === minSaved);
const needySet = new Set(neediest.map((b) => b.name));
const pickIdx = candidateQueue.findIndex((c) => needySet.has(c.board));
if (pickIdx >= 0) {
  return [{
    json: { ...state, useQueue: true, queuePickIndex: pickIdx, searchQuery: '[queue]', firecrawlBody: {},
      currentBoard: candidateQueue[pickIdx].board, resetEmpty },
  }];
}

// 2) Polite pacing (longer after an API error)
if (attempt > 0) {
  const base = Number(cfg.firecrawlDelayMs || 700);
  const delay = state.lastOutcome === 'api_error' ? 5000
    : consec >= 20 ? base * 2 : consec >= 10 ? base * 1.4 : base;
  await new Promise((resolve) => setTimeout(resolve, delay));
}

// 3) Search the neediest board (ties: the one searched least)
const board = neediest.slice().sort((a, b) => (searches[a.name] || 0) - (searches[b.name] || 0))[0];
const bIdx = searches[board.name] || 0;

const roles = cfg.roles && cfg.roles.length ? cfg.roles : ['developer'];
const locations = cfg.locations && cfg.locations.length ? cfg.locations : [''];
const isRemote = (s) => /remote|work from home/i.test(s);
const isAnywhere = (s) => !s || (cfg.anywhereAliases || ['anywhere']).includes(String(s).toLowerCase());
function quote(s) { return s ? `"${s}"` : ''; }

// This board's next role x location combination, then the next query pattern
const combos = [];
for (const r of roles) for (const l of locations) combos.push([r, l]);
const C = combos.length;
const [roleTerm, locTerm] = combos[bIdx % C];
const round = Math.floor(bIdx / C);

const roleOr = roles.length > 1 ? `(${roles.map(quote).join(' OR ')})` : quote(roleTerm);
const locQ = isAnywhere(locTerm) ? '' : isRemote(locTerm) ? 'remote' : quote(locTerm);
const locPlain = isAnywhere(locTerm) ? '' : isRemote(locTerm) ? 'remote' : locTerm;

const sitePart = board.site ? `site:${board.site}` : '(hiring OR careers OR "job opening")';

const patterns = [
  () => `${sitePart} ${quote(roleTerm)} ${locQ}`,
  () => `${sitePart} intitle:${quote(roleTerm)} ${locPlain}`,
  () => `${sitePart} ${quote(roleTerm)} ${locPlain} hiring`,
  () => `${sitePart} ${roleTerm} ${locPlain}`,
];

const clean = (q) => q.replace(/""/g, '').replace(/\s+/g, ' ').trim();
let query = clean(patterns[round % patterns.length]());

// Progressive broadening when stuck (location is always kept)
if (consec >= 12) query = clean(`${sitePart} ${roleOr} ${locPlain}`);
if (consec >= 24) query = clean(`${sitePart} ${roleTerm} ${locPlain}`);

// Exclude postings Google already shows as closed (e.g. LinkedIn "No longer accepting applications")
const exclusions = (cfg.queryExclusions || []).map((p) => `-${p}`).join(' ');
if (exclusions && consec < 30) query = clean(`${query} ${exclusions}`);

let tbs = cfg.tbs;
if (consec >= 25 && tbs === 'qdr:d') tbs = 'qdr:w';
if (consec >= 35 && tbs === 'qdr:w') tbs = 'qdr:m';

const firecrawlBody = { query, limit: consec >= 15 ? 15 : 10 };
if (tbs) firecrawlBody.tbs = tbs;
if (locTerm && !isRemote(locTerm) && !isAnywhere(locTerm) && consec < 12 && bIdx % 2 === 0) {
  firecrawlBody.location = locTerm;
}

return [{
  json: {
    ...state,
    useQueue: false,
    searchQuery: query,
    boardSearchIdx: { ...searches, [board.name]: bIdx + 1 },
    resetEmpty,
    currentBoard: board.name,
    currentCombo: `${roleTerm} @ ${locTerm || 'any'}`,
    firecrawlBody,
    candidateQueue,          // kept: queued results from other boards stay available
  },
}];

// Extract Job Candidate
// Turns Firecrawl search results into one job candidate (and queues the rest).
// Skips listing/search pages, non-posting URLs, closed or stale postings and anything already seen.

const state = $('Build Search Query').item.json;
const cfg = state.config;
const form = state.form;

const boards = cfg.boards.map((b) => ({ ...b, re: new RegExp(b.match, 'i'), rejectRe: b.reject ? new RegExp(b.reject, 'i') : null }));
const MAX_QUEUE = 60;
const excludedDomains = ['youtube.com', 'wikipedia.org', 'facebook.com', 'instagram.com', 'reddit.com'];
const listingTitle = [
  /\b\d[\d,]*\+?\s+.*\bjobs?\b/i,              // "120 Flutter Developer jobs in Lahore"
  /\bjobs?\s*(in|near)\b.*\(with salaries\)/i,
  /\b(vacancies|job openings|jobs and careers)\b/i,
  /^jobs?\s+(in|for)\b/i,
];

const closedRe = new RegExp((cfg.closedPhrases || []).map((p) => p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|') || '$^', 'i');

// "3 days ago", "30+ days ago", "2 weeks ago", "yesterday", "Posted on Oct 12, 2026" -> age in days
function parseAge(text) {
  const t = String(text || '');
  let m = t.match(/(\d+)\+?\s*(minute|min|hour|hr|day|week|wk|month|mo|year|yr)s?\s+ago/i);
  if (m) {
    const n = Number(m[1]);
    const unit = m[2].toLowerCase();
    const days = /^(minute|min|hour|hr)/.test(unit) ? 0 : /^(day)/.test(unit) ? n
      : /^(week|wk)/.test(unit) ? n * 7 : /^(month|mo)/.test(unit) ? n * 30 : n * 365;
    return { days, text: m[0] };
  }
  if ((m = t.match(/\b(just now|today|just posted|new)\b/i))) return { days: 0, text: m[0] };
  if ((m = t.match(/\byesterday\b/i))) return { days: 1, text: m[0] };
  m = t.match(/\b(?:posted|published|date posted)[:\s]*(?:on\s+)?([A-Z][a-z]{2,8}\.? \d{1,2},? \d{4}|\d{4}-\d{2}-\d{2})/i);
  if (m) {
    const d = Date.parse(m[1].replace('.', ''));
    if (!Number.isNaN(d)) return { days: Math.max(0, Math.floor((Date.now() - d) / 86400000)), text: m[1] };
  }
  return null;
}

function normalizeJobUrl(raw) {
  const s = String(raw || '').trim();
  if (!s) return '';
  let u;
  try { u = new URL(s); } catch (e) { return s.toLowerCase().replace(/[?#].*$/, '').replace(/\/+$/, ''); }
  const host = u.hostname.toLowerCase().replace(/^www\./, '');
  if (/(^|\.)linkedin\.com$/.test(host)) {
    const m = u.pathname.match(/\/jobs\/view\/(?:[^/]*?-)?(\d{6,})/);
    if (m) return `https://www.linkedin.com/jobs/view/${m[1]}`;
  }
  if (/(^|\.)indeed\.com$/.test(host)) {
    const jk = u.searchParams.get('jk') || u.searchParams.get('vjk');
    if (jk) return `https://www.indeed.com/viewjob?jk=${jk}`;
  }
  const path = u.pathname.replace(/\/+$/, '');
  return `https://${host}${path}`.toLowerCase();
}

function dedupeSlug(s) {
  return String(s || '').toLowerCase()
    .replace(/\b(pvt|private|ltd|limited|inc|llc|co|company|corp)\b\.?/g, '')
    .replace(/[^a-z0-9]+/g, '');
}

// Seen = URLs handled this run + URLs already in the sheet for this mode
const seen = new Set(state.seenUrls || []);
for (const row of $('Load Existing Leads').all()) {
  const j = row.json || {};
  if (String(j.Mode || '') !== state.modeLabel) continue;
  const u = normalizeJobUrl(j['Job URL']);
  if (u) seen.add(u);
}

function boardFor(url) {
  // Most specific board first; "Any website" last
  const specific = boards.filter((b) => b.site);
  for (const b of specific) {
    if (b.re.test(url)) return b.rejectRe && b.rejectRe.test(url) ? '' : b.name;   // reject = listing/search pages
  }
  const any = boards.find((b) => !b.site);
  return any && any.re.test(url) ? any.name : '';
}

// Heuristic title parse; Gemini refines these later
function parseTitle(title, url) {
  let t = String(title || '').replace(/\s+/g, ' ').trim()
    .replace(/\s*[|\-–—]\s*(LinkedIn|Indeed(\.com)?|Rozee\.pk|Bayt\.com|Greenhouse|Lever)\s*$/i, '')
    .replace(/\s*(\.\.\.|…)\s*$/, '');
  let company = '';
  let role = '';
  let loc = '';
  let m;
  if ((m = t.match(/^(.+?) hiring (.+?) in (.+)$/i))) { [, company, role, loc] = m; }
  else if ((m = t.match(/^Job Application for (.+?) at (.+)$/i))) { [, role, company] = m; }
  else if ((m = t.match(/^(.+?) jobs? in (.+?) at (.+)$/i))) { [, role, loc, company] = m; }
  else {
    const parts = t.split(/\s+[|\-–—]\s+/).map((s) => s.trim()).filter(Boolean);
    if (/jobs\.lever\.co/i.test(url)) { [company = '', role = ''] = parts; }
    else { [role = '', company = '', loc = ''] = parts; }
  }
  if (!company) {
    const gh = url.match(/greenhouse\.io\/([^/]+)\/jobs/i) || url.match(/jobs\.lever\.co\/([^/]+)/i);
    if (gh) company = gh[1].replace(/[-_]+/g, ' ');
  }
  return { company: company.trim(), role: role.trim(), loc: loc.trim() };
}

function basePayload(extra = {}) {
  return {
    ...state,
    hasCandidate: false,
    outcome: 'empty',
    normalizedUrl: '',
    apiError: '',
    'Date Added': $now.toISODate(),
    'Time Added': $now.toFormat('HH:mm:ss'),
    'Mode': state.modeLabel,
    'Company': '',
    'Job Title': '',
    'Location': '',
    'Job Board': '',
    'Job URL': '',
    'Snippet': '',
    'Fit Score': '',
    'Fit Reason': '',
    'Angle / Tip': '',
    'Contact Name': '',
    'Contact Title': '',
    'Contact LinkedIn': '',
    'Search Keywords': cfg.rolesText || '',
    'Run By': form['Your name'] ?? '',
    'Search Run ID': state.searchRunId,
    'Status': state.mode === 'jobs' ? 'To apply' : 'New',
    'Dedupe Key': '',
    'Posted': '',
