const geminiBody = { contents: [{ role: 'user', parts: [{ text: prompt }] }], generationConfig };

return [{
  json: {
    ...lead,
    aiModelIdx: modelIdx,
    aiModelCurrent: model,
    geminiBody,
    lastAiCallAt: Date.now(),
  },
}];

// Parse AI Result
// Reads Gemini's JSON verdict, or classifies the error and decides:
//   retry (same or next model)  ->  aiRetry = true   (loops back to Build AI Prompt)
