//   Closed  -> 404/410, a "no longer accepting / expired / filled" message, or a redirect to a job list
//   Open    -> page loaded and none of the above
//   Unverified -> the page could not be fetched (the lead is kept; better a false positive than a lost lead)

const lead = $('Build Open Check').item.json;
const cfg = lead.config;
const resp = $input.first().json || {};
const out = { ...lead };
delete out.scrapeBody;

const closedRe = new RegExp((cfg.closedPhrases || []).map((p) => p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|') || '$^', 'i');

function parseAge(text) {
  const t = String(text || '');
  const m = t.match(/(\d+)\+?\s*(minute|min|hour|hr|day|week|wk|month|mo|year|yr)s?\s+ago/i);
  if (!m) return null;
  const n = Number(m[1]);
  const u = m[2].toLowerCase();
  const days = /^(minute|min|hour|hr)/.test(u) ? 0 : /^day/.test(u) ? n
    : /^(week|wk)/.test(u) ? n * 7 : /^(month|mo)/.test(u) ? n * 30 : n * 365;
  return { days, text: m[0] };
}

out.stillOpen = true;
out.pageChecked = true;
const data = resp.data || {};
const meta = data.metadata || {};
const status = Number(meta.statusCode || 0);
const md = String(data.markdown || '');

if (resp.success === false || resp.error || (!md && !status)) {
  out['Open Check'] = 'Unverified (page check failed)';
} else if (status === 404 || status === 410) {
  out.stillOpen = false;
  out['Open Check'] = `Closed (HTTP ${status})`;
} else {
  const finalUrl = String(meta.url || meta.sourceURL || '');
  const redirectedAway = finalUrl && (/[?&]error=true/i.test(finalUrl) ||
    (/greenhouse\.io|lever\.co/i.test(lead['Job URL']) && !/\/jobs?\/|lever\.co\/[^/]+\/[0-9a-f-]{8,}/i.test(finalUrl)));
  const head = md.slice(0, 4000);   // closed banners are near the top
  const closedMatch = head.match(closedRe);
  const age = parseAge(head);
  const maxAge = Number(cfg.maxAgeDays || 0);

  if (closedMatch) {
    out.stillOpen = false;
    out['Open Check'] = `Closed ("${closedMatch[0]}")`;
  } else if (redirectedAway) {
    out.stillOpen = false;
    out['Open Check'] = 'Closed (redirected to job list)';
  } else if (age && maxAge && age.days > maxAge) {
    out.stillOpen = false;
    out['Open Check'] = `Stale (${age.text})`;
  } else {
    out['Open Check'] = 'Open (page checked)';
  }
  if (age && !out['Posted']) out['Posted'] = age.text;
}

if (!out.stillOpen) out.outcome = 'closed';
return [{ json: out }];

// Build Contact Query
// Clients mode only: search LinkedIn profiles for a decision-maker at the hiring company.

const lead = $input.first().json;
const cfg = lead.config;

const company = String(lead['Company'] || '').replace(/"/g, '').trim();
// The location this job matched, else the first non-remote location picked on the form
const city = String(lead.matchedLocation || (cfg.locations || []).find((l) => !/remote|anywhere|worldwide|global/i.test(l)) || '').trim();
const cityPart = city && !/remote|anywhere|worldwide|global/i.test(city) ? city : '';
const roles = (cfg.contactRoles || []).join(' OR ');

const query = `site:linkedin.com/in/ "${company}" (${roles}) ${cityPart}`.replace(/\s+/g, ' ').trim();

return [{ json: { ...lead, contactBody: { query, limit: 5 } } }];

// Extract Contact
// Picks the first LinkedIn profile that clearly mentions the company. Leaves blanks if unsure.

const lead = $('Build Contact Query').item.json;
const resp = $input.first().json || {};
const out = { ...lead };
delete out.contactBody;

const results = Array.isArray(resp?.data?.web) ? resp.data.web
  : Array.isArray(resp?.data) ? resp.data : [];

const generic = new Set(['pvt', 'private', 'ltd', 'limited', 'inc', 'llc', 'the', 'and', 'company',
  'group', 'solutions', 'technologies', 'technology', 'tech', 'software', 'services', 'international']);
const tokens = String(lead['Company'] || '').toLowerCase().split(/[^a-z0-9]+/)
  .filter((t) => t.length >= 3 && !generic.has(t));

function parsePerson(title) {
  const cleaned = String(title || '').replace(/\s+/g, ' ').trim()
    .replace(/\s*[-–—|]\s*LinkedIn\s*$/i, '');
  const parts = cleaned.split(/\s+[-–—|]\s+/).map((s) => s.trim()).filter(Boolean);
  return { name: parts[0] || '', title: parts[1] || '' };
}

if (tokens.length) {
  for (const r of results) {
    const url = String(r.url || '');
    const m = url.match(/linkedin\.com\/in\/([^/?#]+)/i);
    if (!m) continue;
    const hay = `${r.title || ''} ${r.description || ''}`.toLowerCase();
    if (!tokens.some((t) => hay.includes(t))) continue;
    const p = parsePerson(r.title);
    out['Contact Name'] = p.name;
    out['Contact Title'] = p.title;
    out['Contact LinkedIn'] = `https://www.linkedin.com/in/${decodeURIComponent(m[1]).toLowerCase()}`;
    break;
  }
}

return [{ json: out }];

// Prepare Row
// Single entry point before writing to the sheet (with or without contact lookup).
// Maps the internal fields onto the clean, human-facing Leads columns.

const lead = $input.first().json;
const name = String(lead['Contact Name'] || '').trim();
const title = String(lead['Contact Title'] || '').trim();

return [{
  json: {
    ...lead,
    'Why It Fits': lead['Fit Reason'] || '',
    'Pitch / Tip': lead['Angle / Tip'] || '',
    'Contact': name ? (title ? `${name} (${title})` : name) : '',
    'Contact LinkedIn': lead['Contact LinkedIn'] || '',
    'Run ID': lead.searchRunId || lead['Search Run ID'] || '',
  },
}];

// Tag Created
const lead = $('Prepare Row').item.json;
return [{ json: { ...lead, outcome: 'created' } }];

// Tag Missed (no usable search result) / Tag Skipped (rejected by AI) share this logic
const lead = $input.first().json;
return [{
  json: {
    ...lead,
    outcome: lead.outcome && !['candidate', 'qualified', 'pending_ai'].includes(lead.outcome) ? lead.outcome : 'invalid',
  },
}];

// Tag Missed (no usable search result) / Tag Skipped (rejected by AI) share this logic
const lead = $input.first().json;
return [{
  json: {
    ...lead,
    outcome: lead.outcome && !['candidate', 'qualified', 'pending_ai'].includes(lead.outcome) ? lead.outcome : 'invalid',
  },
}];

// Update Counters
// Records the outcome of this pass and decides whether the loop continues.

const c = $input.first().json;
const cfg = c.config;
const outcome = c.outcome || 'invalid';

let newLeadsSaved = Number(c.newLeadsSaved || 0);
let lowFitCount = Number(c.lowFitCount || 0);
let duplicateCount = Number(c.duplicateCount || 0);
let notJobCount = Number(c.notJobCount || 0);
let aiErrorCount = Number(c.aiErrorCount || 0);
let closedCount = Number(c.closedCount || 0);
let wrongLocationCount = Number(c.wrongLocationCount || 0);
let pageCheckedCount = Number(c.pageCheckedCount || 0) + (c.pageChecked ? 1 : 0);

// Per-board balance tracking (see Build Search Query)
const savedByBoard = { ...(c.savedByBoard || {}) };
const missesByBoard = c.resetEmpty ? {} : { ...(c.missesByBoard || {}) };
if (outcome === 'created' && c['Job Board']) savedByBoard[c['Job Board']] = (savedByBoard[c['Job Board']] || 0) + 1;
// Every pass is attributed to a board (the one searched, or the queued result's board).
// Misses in a row = results from that board that were not saved; a save resets it.
const passBoard = c['Job Board'] || c.currentBoard;
if (passBoard) missesByBoard[passBoard] = outcome === 'created' ? 0 : (missesByBoard[passBoard] || 0) + 1;
let aiFallbackCount = Number(c.aiFallbackCount || 0);
let consecutiveUnsuccessfulAttempts = Number(c.consecutiveUnsuccessfulAttempts || 0);
let consecutiveApiErrors = Number(c.consecutiveApiErrors || 0);
let lastApiError = c.lastApiError || '';
const attemptIndex = Number(c.attemptIndex || 0) + 1;

const seenUrls = Array.isArray(c.seenUrls) ? [...c.seenUrls] : [];
const seenKeys = Array.isArray(c.seenKeys) ? [...c.seenKeys] : [];
if (c.normalizedUrl && !seenUrls.includes(c.normalizedUrl)) seenUrls.push(c.normalizedUrl);
const key = c['Dedupe Key'];
if (key && ['created', 'low_fit', 'not_job', 'duplicate', 'closed', 'wrong_location'].includes(outcome) && !seenKeys.includes(key)) {
  seenKeys.push(key);
}

if (outcome === 'created') { newLeadsSaved += 1; consecutiveUnsuccessfulAttempts = 0; }
else consecutiveUnsuccessfulAttempts += 1;

if (outcome === 'low_fit') lowFitCount += 1;
if (outcome === 'duplicate') duplicateCount += 1;
if (outcome === 'not_job') notJobCount += 1;
if (outcome === 'wrong_location') wrongLocationCount += 1;
closedCount += Number(c.closedFiltered || 0);
if (outcome === 'closed' && !c.closedFiltered) closedCount += 1;
if (c.aiError) { aiErrorCount += 1; aiFallbackCount += 1; }

if (outcome === 'api_error') { consecutiveApiErrors += 1; lastApiError = c.apiError || lastApiError; }
else consecutiveApiErrors = 0;

const maxApi = Number(cfg.maxConsecutiveApiErrors || 3);
const shouldContinue =
  newLeadsSaved < c.targetLeads &&
  consecutiveUnsuccessfulAttempts < c.maxRetries &&
  consecutiveApiErrors < maxApi &&
  attemptIndex < c.maxAttempts;

let status = 'running';
if (newLeadsSaved >= c.targetLeads) status = 'target_reached';
else if (consecutiveApiErrors >= maxApi) status = 'api_error';
else if (consecutiveUnsuccessfulAttempts >= c.maxRetries) status = 'retry_limit_reached';
else if (attemptIndex >= c.maxAttempts) status = 'max_attempts_reached';

return [{
  json: {
    form: c.form,
    mode: c.mode,
    modeLabel: c.modeLabel,
    config: cfg,
    targetLeads: c.targetLeads,
    newLeadsSaved,
    lowFitCount,
    duplicateCount,
    notJobCount,
    aiErrorCount,
    aiFallbackCount,
    closedCount,
    wrongLocationCount,
    consecutiveAiFailures: Number(c.consecutiveAiFailures || 0),
    aiDisabled: Boolean(c.aiDisabled),
    aiModelIdxRun: Number(c.aiModelIdxRun || 0),
    aiNoThinkingRun: Boolean(c.aiNoThinkingRun),
    lastAiError: c.lastAiError || '',
    consecutiveUnsuccessfulAttempts,
    consecutiveApiErrors,
    lastApiError,
    lastAiCallAt: c.lastAiCallAt || 0,
    maxRetries: c.maxRetries,
    maxAttempts: c.maxAttempts,
    attemptIndex,
    savedByBoard,
    missesByBoard,
    boardSearchIdx: c.boardSearchIdx || {},
    pageCheckedCount,
    seenUrls,
    seenKeys,
    candidateQueue: Array.isArray(c.candidateQueue) ? c.candidateQueue : [],
    existingLeadCount: c.existingLeadCount,
    searchRunId: c.searchRunId,
    startedAt: c.startedAt,
    shouldContinue,
    lastOutcome: outcome,
    status,
    useQueue: false,
  },
}];

// Run Summary
// One row per run for the "Run Log" tab: what was searched, by whom, and what happened.

const s = $input.first().json;
const cfg = s.config;
const models = cfg.aiModels || [];
const saved = s.savedByBoard || {};
const searches = Object.values(s.boardSearchIdx || {}).reduce((a, b) => a + Number(b || 0), 0);
const tbsLabel = { 'qdr:d': 'Past 24 hours', 'qdr:w': 'Past week', 'qdr:m': 'Past month', '': 'Any time' };

return [{
  json: {
    'Run ID': s.searchRunId,
    'Date': $now.toISODate(),
    'Time': $now.toFormat('HH:mm:ss'),
    'Run By': s.form['Your name'] || '',
    'Mode': s.modeLabel,
    'Roles': cfg.rolesText || '',
    'Locations': (cfg.locationsText || '') + (cfg.strictLocation ? '' : ' (not filtered)'),
    'Boards': (cfg.boards || []).map((b) => b.name).join(', '),
    'Posted Within': tbsLabel[cfg.tbs] ?? cfg.tbs,
    'Ranking': cfg.rankingLabel || '',
    'AI Model': cfg.useAi ? (models[s.aiModelIdxRun || 0] || '') + (s.aiDisabled ? ' (paused: errors)' : '') : '',
    'Min Score': cfg.rankingMode === 'none' ? '' : cfg.minScore,
    'Target': s.targetLeads,
    'Saved': s.newLeadsSaved,
    'Saved By Board': (cfg.boards || []).map((b) => `${b.name}: ${saved[b.name] || 0}`).join(', '),
    'Low Fit': s.lowFitCount,
    'Duplicates': s.duplicateCount,
    'Closed': s.closedCount,
    'Wrong Location': s.wrongLocationCount,
    'Not A Job': s.notJobCount,
    'Page Checked': s.pageCheckedCount,
    'Searches': searches,
    'Attempts': s.attemptIndex,
    'AI Errors': s.aiErrorCount,
    'Status': s.status,
    'Last Error': s.lastApiError || s.lastAiError || '',
  },
}];
